import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';

function App() {
  return (
    <Router>
      <div>
        <h1>Pet Adoption Platform</h1>
        <nav>
          <Link to="/">Home</Link> | 
          <Link to="/test">Test</Link>
        </nav>
        <Routes>
          <Route path="/" element={<h2>Home Page - React is Working!</h2>} />
          <Route path="/test" element={<h2>Test Page - If you see this, routing works!</h2>} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
